result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_bond.py", "content": "import pytest

from bond import macaulay_duration, modified_duration, price


def test_price_at_par():
    """2y annual 5% coupon, face 100, yield 5% -> exactly 100.00."""
    assert price(100, 0.05, 0.05, 2) == pytest.approx(100.00)


def test_macaulay_duration_two_year():
    """Same bond has Macaulay duration 1.9524."""
    assert macaulay_duration(100, 0.05, 0.05, 2) == pytest.approx(
        1.9524, abs=1e-3
    )


def test_zero_coupon_duration_equals_maturity():
    assert macaulay_duration(100, 0.0, 0.06, 10) == pytest.approx(10.0)


@pytest.mark.parametrize("y", [0.03, 0.04])
def test_premium_below_coupon_yield(y):
    assert price(100, 0.05, y, 10) > 100


@pytest.mark.parametrize("y", [0.06, 0.07])
def test_discount_above_coupon_yield(y):
    assert price(100, 0.05, y, 10) < 100


@pytest.mark.parametrize("freq", [1, 2, 4])
def test_modified_is_macaulay_over_one_plus_y(freq):
    m = macaulay_duration(100, 0.05, 0.04, 7, freq)
    mod = modified_duration(100, 0.05, 0.04, 7, freq)
    assert mod == pytest.approx(m / (1 + 0.04 / freq))


def test_finite_difference_matches_modified_duration():
    face, c, y, years, freq = 100, 0.05, 0.05, 10, 2
    bp = 1e-4  # 1 basis point as a decimal
    up = price(face, c, y + bp, years, freq)
    dn = price(face, c, y - bp, years, freq)
    fd = (dn - up) / (2 * price(face, c, y, years, freq) * bp)
    assert fd == pytest.approx(modified_duration(face, c, y, years, freq), abs=1e-4)
